class ScheduleScreen extends StatefulWidget { const ScheduleScreen({super.key}); @override State<ScheduleScreen> createState() => _ScheduleScreenState(); }
class _ScheduleScreenState extends State<ScheduleScreen> {
  int selectedDay = DateTime.now().weekday;
  @override Widget build(BuildContext context) { final s = context.watch<AppState>(); final items = s.schedule.where((x) => x.weekdays.contains(selectedDay)).toList()..sort((a,b)=>a.startMinutes.compareTo(b.startMinutes)); return Scaffold(backgroundColor: canvas, body: CustomScrollView(slivers: [SliverToBoxAdapter(child: AppPageHeader(eyebrow: 'Planner', title: 'Daily schedule', subtitle: 'Check the day before you promise a time.', actions: [IconButton(onPressed: () => _quickAvailability(context, s), icon: const Icon(Icons.bolt_rounded))])), SliverToBoxAdapter(child: _dayStrip()), if (items.isEmpty) SliverFillRemaining(child: EmptyState(icon: Icons.calendar_month_rounded, title: 'No blocks for this day', message: 'Add your recurring routine — chambers, court, drafting, calls and client meetings.', actionLabel: 'Add schedule', onAction: () => _edit(context))), SliverPadding(padding: const EdgeInsets.fromLTRB(20, 16, 20, 90), sliver: SliverList.builder(itemCount: items.length, itemBuilder: (_, i) => Padding(padding: const EdgeInsets.only(bottom: 12), child: _ScheduleCard(item: items[i], onEdit: () => _edit(context, items[i]), onDelete: () async => s.deleteSchedule(items[i])))))])); }
  Widget _dayStrip() => SizedBox(height: 92, child: ListView.separated(padding: const EdgeInsets.symmetric(horizontal: 20), scrollDirection: Axis.horizontal, itemCount: 7, separatorBuilder: (_, _) => const SizedBox(width: 8), itemBuilder: (_, i) { final d = i + 1; final active = d == selectedDay; final name = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]; return InkWell(onTap: () => setState(() => selectedDay = d), borderRadius: BorderRadius.circular(18), child: AnimatedContainer(duration: const Duration(milliseconds: 180), width: 70, padding: const EdgeInsets.symmetric(vertical: 12), decoration: BoxDecoration(color: active ? ink : Colors.white, borderRadius: BorderRadius.circular(18), border: Border.all(color: active ? ink : ink.withValues(alpha: .06))), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Text(name, style: TextStyle(color: active ? gold : muted, fontWeight: FontWeight.w800, fontSize: 12)), const SizedBox(height: 6), Text('$d', style: TextStyle(color: active ? Colors.white : ink, fontSize: 18, fontWeight: FontWeight.w900))]))); }));
  Future<void> _edit(BuildContext context, [ScheduleItem? existing]) async { showModalBottomSheet(context: context, isScrollControlled: true, showDragHandle: true, builder: (_) => _ScheduleEditor(existing: existing)); }
  Future<void> _quickAvailability(BuildContext context, AppState s) async { await showDialog(context: context, builder: (_) => _AvailabilityDialog(state: s)); }
}

class _ScheduleCard extends StatelessWidget { final ScheduleItem item; final VoidCallback onEdit; final VoidCallback onDelete; const _ScheduleCard({required this.item, required this.onEdit, required this.onDelete}); @override Widget build(BuildContext context) => Dismissible(key: ValueKey(item.id), background: Container(margin: const EdgeInsets.only(bottom: 12), padding: const EdgeInsets.only(right: 20), decoration: BoxDecoration(color: danger, borderRadius: BorderRadius.circular(24)), alignment: Alignment.centerRight, child: const Icon(Icons.delete_outline, color: Colors.white)), direction: DismissDirection.endToStart, confirmDismiss: (_) async { onDelete(); return true; }, child: SurfaceCard(onTap: onEdit, child: Row(children: [Text(formatMinutes(item.startMinutes), style: const TextStyle(fontWeight: FontWeight.w900, color: ink, fontSize: 13)), const SizedBox(width: 14), Container(width: 4, height: 52, decoration: BoxDecoration(color: gold, borderRadius: BorderRadius.circular(10))), const SizedBox(width: 12), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(item.title, style: const TextStyle(fontWeight: FontWeight.w900, color: ink)), const SizedBox(height: 5), Text('${formatMinutes(item.endMinutes)} • ${item.category}${item.location.isEmpty ? '' : ' • ${item.location}'}', style: const TextStyle(fontSize: 12, color: muted))])), Icon(item.reminderEnabled ? Icons.notifications_active_outlined : Icons.notifications_off_outlined, color: item.reminderEnabled ? gold : muted, size: 19)]))); }

class _ScheduleEditor extends StatefulWidget { final ScheduleItem? existing; const _ScheduleEditor({this.existing}); @override State<_ScheduleEditor> createState() => _ScheduleEditorState(); }
class _ScheduleEditorState extends State<_ScheduleEditor> { late final TextEditingController title, location, notes; String category = 'Work'; TimeOfDay start = const TimeOfDay(hour: 9, minute: 0), end = const TimeOfDay(hour: 10, minute: 0); final days = <int>{1,2,3,4,5}; bool reminder = true; @override void initState() { super.initState(); final x = widget.existing; title = TextEditingController(text: x?.title ?? ''); location = TextEditingController(text: x?.location ?? ''); notes = TextEditingController(text: x?.notes ?? ''); category = x?.category ?? 'Work'; start = _tod(x?.startMinutes ?? 540); end = _tod(x?.endMinutes ?? 600); days..clear()..addAll(x?.weekdays ?? {1,2,3,4,5}); reminder = x?.reminderEnabled ?? true; } TimeOfDay _tod(int m)=>TimeOfDay(hour:m~/60,minute:m%60); @override void dispose(){title.dispose();location.dispose();notes.dispose();super.dispose();} @override Widget build(BuildContext context){return Padding(padding: EdgeInsets.fromLTRB(20, 10, 20, MediaQuery.viewInsetsOf(context).bottom+24), child: SingleChildScrollView(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Text(widget.existing==null?'Add schedule block':'Edit schedule block',style:const TextStyle(fontSize:21,fontWeight:FontWeight.w900,color:ink)),const SizedBox(height:14),TextField(controller:title,decoration:fieldDecoration('Title',hint:'Chambers / client call / drafting')),const SizedBox(height:12),DropdownButtonFormField<String>(initialValue:category,decoration:fieldDecoration('Category'),items:['Work','Court','Client','Drafting','Personal','Travel'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>category=v??category)),const SizedBox(height:12),Row(children:[Expanded(child:_time('Starts',start,()=>_pick(true))),const SizedBox(width:12),Expanded(child:_time('Ends',end,()=>_pick(false)))]),const SizedBox(height:12),const Text('Repeats on',style:TextStyle(fontSize:12,color:muted,fontWeight:FontWeight.w700)),const SizedBox(height:8),Wrap(spacing:7,children:[for(int d=1;d<=7;d++)FilterChip(label:Text(['M','T','W','T','F','S','S'][d-1]),selected:days.contains(d),onSelected:(v)=>setState(()=>v?days.add(d):days.remove(d)))]),const SizedBox(height:12),TextField(controller:location,decoration:fieldDecoration('Location')),const SizedBox(height:12),TextField(controller:notes,maxLines:3,decoration:fieldDecoration('Notes')),SwitchListTile(contentPadding:EdgeInsets.zero,value:reminder,onChanged:(v)=>setState(()=>reminder=v),title:const Text('Remind me 30 minutes before',style:TextStyle(fontWeight:FontWeight.w700)),activeThumbColor:gold),const SizedBox(height:8),FilledButton(onPressed:_save,child:const SizedBox(width:double.infinity,child:Center(child:Text('Save schedule'))))]))); } Widget _time(String label,TimeOfDay t,VoidCallback tap)=>InkWell(onTap:tap,borderRadius:BorderRadius.circular(16),child:Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16),border:Border.all(color:ink.withValues(alpha:.07))),child:Row(children:[const Icon(Icons.schedule_rounded,color:gold,size:17),const SizedBox(width:7),Expanded(child:Text('$label\n${t.format(context)}',style:const TextStyle(fontWeight:FontWeight.w800,color:ink))) ]))); Future<void> _pick(bool isStart) async {final picked=await showTimePicker(context:context,initialTime:isStart?start:end);if(picked!=null)setState(()=>isStart?start=picked:end=picked);} Future<void> _save() async {if(title.text.trim().isEmpty||days.isEmpty)return;final sm=start.hour*60+start.minute, em=end.hour*60+end.minute;if(em<=sm){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('End time must be after start time.')));return;}final state=context.read<AppState>();final allConflicts=<int,List<ScheduleItem>>{};for(final day in days){final hits=state.conflictsFor(sm,em,weekday:day,ignoreId:widget.existing?.id);if(hits.isNotEmpty)allConflicts[day]=hits;}if(allConflicts.isNotEmpty){final day=allConflicts.keys.first;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Conflict on ${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][day-1]} with ${allConflicts[day]!.first.title}.')));return;}await state.upsertSchedule(ScheduleItem(id:widget.existing?.id??state.newId(),title:title.text.trim(),category:category,startMinutes:sm,endMinutes:em,weekdays:days,location:location.text.trim(),notes:notes.text.trim(),reminderEnabled:reminder));if(mounted)Navigator.pop(context);} }

class _AvailabilityDialog extends StatefulWidget { final AppState state; const _AvailabilityDialog({required this.state}); @override State<_AvailabilityDialog> createState()=>_AvailabilityDialogState(); }
class _AvailabilityDialogState extends State<_AvailabilityDialog> { TimeOfDay start=const TimeOfDay(hour:10,minute:0),end=const TimeOfDay(hour:11,minute:0); @override Widget build(BuildContext context){final sm=start.hour*60+start.minute,em=end.hour*60+end.minute;final conflicts=widget.state.conflictsFor(sm,em,weekday:DateTime.now().weekday);return AlertDialog(title:const Text('Before giving a time'),content:Column(mainAxisSize:MainAxisSize.min,children:[_t('From',start,()=>_pick(true)),const SizedBox(height:8),_t('To',end,()=>_pick(false)),const SizedBox(height:14),Row(children:[Icon(conflicts.isEmpty?Icons.check_circle_rounded:Icons.warning_rounded,color:conflicts.isEmpty?success:danger),const SizedBox(width:9),Expanded(child:Text(conflicts.isEmpty?'No recurring conflict today.':'Conflict: ${conflicts.map((e)=>e.title).join(', ')}',style:const TextStyle(fontWeight:FontWeight.w700)))])]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Close')),if(conflicts.isEmpty)FilledButton(onPressed:()=>Navigator.pop(context),child:const Text('Looks free'))]);} Widget _t(String l,TimeOfDay t,VoidCallback onTap)=>ListTile(contentPadding:EdgeInsets.zero,onTap:onTap,title:Text(l),trailing:Text(t.format(context),style:const TextStyle(fontWeight:FontWeight.w900,color:ink)));Future<void>_pick(bool a)async{final p=await showTimePicker(context:context,initialTime:a?start:end);if(p!=null)setState(()=>a?start=p:end=p);} }
